parameters.query:
SELECT json_build_object(
  'active_profile', (SELECT row_to_json(t) FROM (SELECT studio_id, identity, tone, priorities, red_lines, visit_checklist, materials_pref, trades_pref, jurisdiction, setup_source, setup_completed_at, created_at, updated_at, notes FROM studio_profile WHERE active=true ORDER BY setup_completed_at DESC NULLS LAST, created_at DESC LIMIT 1) t),
  'inactive_profiles', coalesce((SELECT json_agg(t.* ORDER BY t.created_at DESC) FROM (SELECT studio_id, setup_source, setup_completed_at, created_at, identity->>'nombre_estudio' AS name FROM studio_profile WHERE active=false LIMIT 10) t), '[]'::json),
  'sessions', coalesce((SELECT json_agg(t.* ORDER BY t.started_at DESC) FROM (SELECT id, status, sections_covered, started_at, last_message_at, completed_at, llm_total_cost_usd, llm_message_count, contact_email FROM onboarding_sessions LIMIT 10) t), '[]'::json),
  'session_in_progress', (SELECT count(*) FROM onboarding_sessions WHERE status='in_progress')::int
) AS report;

parameters.jsCode:
const r = $input.first().json.report || {};
const active = r.active_profile;
const inactive = Array.isArray(r.inactive_profiles) ? r.inactive_profiles : [];
const sessions = Array.isArray(r.sessions) ? r.sessions : [];
const sessionInProgress = r.session_in_progress || 0;

function esc(s) { return String(s == null ? '' : s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
function dateShort(s) { if (!s) return '-'; return new Date(s).toISOString().substring(0,16).replace('T',' '); }
function money(n) { return n != null ? '$' + Number(n).toFixed(4) : '$0'; }

function parseJson(j) { if (j == null) return {}; if (typeof j === 'string') { try { return JSON.parse(j); } catch(e) { return {}; } } return j; }

function renderSection(title, data, formatter) {
  return `<div class="section"><h3>${esc(title)}</h3>${data ? formatter(data) : '<p class="empty">(sin datos)</p>'}</div>`;
}

let activeHtml = '<p class="empty">Sin profile activo.</p>';
if (active) {
  const id = parseJson(active.identity);
  const tone = parseJson(active.tone);
  const priorities = parseJson(active.priorities);
  const redLines = parseJson(active.red_lines);
  const visit = parseJson(active.visit_checklist);
  const mat = parseJson(active.materials_pref);
  const tr = parseJson(active.trades_pref);
  const jur = parseJson(active.jurisdiction);
  const sourceColor = { onboarding_chat: '#10b981', baseline: '#9ca3af', admin_edit: '#3b82f6', manual: '#6b7280' }[active.setup_source] || '#6b7280';
  activeHtml = `<div class="active-card">
    <div class="badge" style="background:${sourceColor}">${esc(active.setup_source)}</div>
    <h2>${esc(id.nombre_estudio || '(sin nombre)')}</h2>
    <p class="meta">${esc(id.persona_principal || '?')} · ${esc(id.ciudad || '?')} · ${id.anos_exp || 0} años exp · colegiado ${esc(id.colegiado_no || '-')}</p>
    <p class="meta">studio_id: <code>${esc(active.studio_id)}</code> · setup ${dateShort(active.setup_completed_at)} · updated ${dateShort(active.updated_at)}</p>
    ${renderSection('1. Identidad', id, d => `<table><tr><td>Ámbito</td><td>${(d.ambito||[]).map(esc).join(', ')||'-'}</td></tr><tr><td>Tamaño</td><td>${esc(d.tamano||'-')}</td></tr></table>`)}
    ${renderSection('2. Tono comunicacion', tone, d => `<table>${Object.entries(d).map(([k,v]) => `<tr><td>${esc(k)}</td><td>${esc(typeof v === 'object' ? JSON.stringify(v) : v)}</td></tr>`).join('')}</table>`)}
    ${renderSection('3. Prioridades absolutas', priorities, d => Array.isArray(d) && d.length ? '<ol>' + d.map(p => `<li><strong>${esc(p.prioridad||'?')}</strong>${p.detalle ? ' — ' + esc(p.detalle) : ''}</li>`).join('') + '</ol>' : '<p class="empty">vacio</p>')}
    ${renderSection('4. Líneas rojas', redLines, d => Array.isArray(d) && d.length ? '<ul>' + d.map(l => `<li>${esc(l.texto || l.id || JSON.stringify(l))}</li>`).join('') + '</ul>' : '<p class="empty">vacio</p>')}
    ${renderSection('5. Visita inicial - checklist', visit, d => Array.isArray(d) && d.length ? '<ul>' + d.map(v => `<li>${esc(v.pregunta || JSON.stringify(v))}</li>`).join('') + '</ul>' : '<p class="empty">vacio</p>')}
    ${renderSection('6. Materiales preferidos', mat, d => `<p>Gama default: <strong>${esc(d.gama_default || '?')}</strong> · prefiere local: ${d.prefiere_local ? 'si' : 'no'}</p>`)}
    ${renderSection('7. Gremios', tr, d => `<p>${(d.criterios_seleccion || []).length} criterios definidos · ${Object.keys(d.trade_to_contact || {}).length} contactos mapeados</p>`)}
    ${renderSection('8. Jurisdicción', jur, d => `<p><strong>${esc(d.ccaa || '?')}</strong> · ${(d.ayuntamientos_habituales||[]).length} ayuntamientos habituales</p>`)}
  </div>`;
}

const sessionRows = sessions.length ? sessions.map(s => {
  const sec = parseJson(s.sections_covered);
  const covered = Object.values(sec).filter(v => v).length;
  return `<tr>
    <td><code style="font-size:11px">${esc(s.id.substring(0,8))}</code></td>
    <td>${esc(s.status)}</td>
    <td style="text-align:right">${covered}/8</td>
    <td>${esc(s.contact_email || '-')}</td>
    <td>${dateShort(s.started_at)}</td>
    <td>${dateShort(s.completed_at)}</td>
    <td style="text-align:right">${s.llm_message_count || 0}</td>
    <td style="text-align:right">${money(s.llm_total_cost_usd)}</td>
  </tr>`;
}).join('') : '<tr><td colspan="8" style="text-align:center;color:#888;padding:18px">Sin sesiones</td></tr>';

const inactiveRows = inactive.length ? inactive.map(p => `<tr><td><code>${esc(p.studio_id.substring(0,8))}</code></td><td>${esc(p.setup_source)}</td><td>${esc(p.name || '-')}</td><td>${dateShort(p.created_at)}</td></tr>`).join('') : '<tr><td colspan="4" style="text-align:center;color:#888;padding:14px">Sin profiles inactivos</td></tr>';

const html = `<!DOCTYPE html><html lang="es"><head><meta charset="utf-8"><title>Studio Profile - ArquitAI</title>
<style>
  body{font-family:system-ui,sans-serif;max-width:1100px;margin:32px auto;padding:0 20px;color:#222;background:#f7f7f8}
  h1{margin:0 0 8px} h2{margin:0 0 8px;font-size:22px} h3{margin:18px 0 8px;font-size:15px;color:#374151}
  .sub{color:#888;font-size:13px;margin-bottom:24px}
  .active-card{background:#fff;border:1px solid #ddd;border-radius:10px;padding:24px;margin-bottom:24px;position:relative}
  .badge{position:absolute;top:14px;right:14px;color:white;padding:4px 10px;border-radius:10px;font-size:11px;font-weight:600}
  .meta{color:#6b7280;font-size:13px;margin:0 0 12px} .meta code{background:#f3f4f6;padding:2px 4px;border-radius:3px;font-size:12px}
  .section{margin-top:18px;padding-top:14px;border-top:1px solid #f3f4f6}
  .section table{width:100%;border-collapse:collapse;font-size:13px}
  .section table td{padding:4px 8px;border-bottom:1px solid #f3f4f6}
  .section table td:first-child{color:#6b7280;width:30%}
  .section ul, .section ol{margin:8px 0;padding-left:20px;font-size:13px}
  .section .empty{color:#9ca3af;font-style:italic;font-size:13px;margin:0}
  table.list{width:100%;border-collapse:collapse;background:#fff;border:1px solid #ddd;border-radius:8px;overflow:hidden;font-size:13px;margin-top:14px}
  table.list th,table.list td{padding:8px 12px;border-bottom:1px solid #eee;text-align:left}
  table.list th{background:#f0f0f3;font-weight:600;font-size:11px;text-transform:uppercase;color:#555}
  table.list tr:last-child td{border-bottom:none}
  .actions{display:flex;gap:10px;margin-top:14px}
  .actions a{display:inline-block;padding:8px 14px;background:#3b82f6;color:#fff;text-decoration:none;border-radius:6px;font-size:13px}
  .actions a.secondary{background:#fff;color:#3b82f6;border:1px solid #3b82f6}
  .alert{background:#fef3c7;border-left:3px solid #f59e0b;padding:10px 14px;border-radius:4px;font-size:13px;color:#78350f;margin-bottom:18px}
  .meta-foot{font-size:12px;color:#888;margin-top:24px}
</style></head><body>
<h1>Studio Profile - ArquitAI</h1>
<p class="sub">Perfil del estudio activo + historico. Para iniciar onboarding o reconfigurar, abre el chat.</p>
${sessionInProgress > 0 ? `<div class="alert">Hay ${sessionInProgress} sesion(es) de onboarding en progreso. Continua o cierra desde el chat.</div>` : ''}
<div class="actions">
  <a href="/webhook/setup-onboarding">Iniciar / continuar onboarding chat</a>
  <a href="/webhook/admin-index" class="secondary">Volver al admin index</a>
</div>
${activeHtml}
<h2 style="margin-top:32px;font-size:18px">Sesiones de onboarding (últimas 10)</h2>
<table class="list"><thead><tr><th>id</th><th>status</th><th style="text-align:right">cubierto</th><th>contacto</th><th>iniciado</th><th>completado</th><th style="text-align:right">msgs</th><th style="text-align:right">coste LLM</th></tr></thead><tbody>${sessionRows}</tbody></table>
<h2 style="margin-top:32px;font-size:18px">Profiles inactivos (historico)</h2>
<table class="list"><thead><tr><th>studio_id</th><th>source</th><th>nombre</th><th>creado</th></tr></thead><tbody>${inactiveRows}</tbody></table>
<div class="meta-foot">Generado ${new Date().toISOString()}</div>
</body></html>`;

return [{ json: { html } }];
